import itertools

CAPACITIES = [4, 3, 6, 2, 5]
SHIPMENTS = [2, 3, 1, 4]
N = len(SHIPMENTS)

def can_place_all(days):
    remaining = list(CAPACITIES)
    for i in days:
        s = SHIPMENTS[i]
        placed = False
        for bay in range(i, 5):
            if remaining[bay] >= s:
                remaining[bay] -= s
                placed = True
                break
        if not placed:
            return False
    return True

skippable = 0
max_delivered = 0

for r in range(N + 1):
    for combo in itertools.combinations(range(N), r):
        if can_place_all(combo):
            skippable += 1
            if r > max_delivered:
                max_delivered = r

print(f"Skippable subsets: {skippable}")
print(f"Max shipments delivered: {max_delivered}")

import itertools

def solve():
    total = 0
    a_full = 0
    # Iterate over all distributions of 7 books into 5 shelves (A-E)
    # Each shelf can hold 0 to 3 books.
    # We need non-increasing counts: A >= B >= C >= D >= E
    for a in range(4):
        for b in range(4):
            if b > a:
                continue
            for c in range(4):
                if c > b:
                    continue
                for d in range(4):
                    if d > c:
                        continue
                    for e in range(4):
                        if e > d:
                            continue
                        if a + b + c + d + e == 7:
                            total += 1
                            if a == 3:
                                a_full += 1
    print(f"Distributions: {total}")
    print(f"Distributions with shelf A full: {a_full}")

