def is_prime(n):
    if n < 2:
        return False
    if n < 4:
        return True
    if n % 2 == 0:
        return False
    i = 3
    while i * i <= n:
        if n % i == 0:
            return False
        i += 2
    return True

def is_increasing(n):
    s = str(n)
    for i in range(1, len(s)):
        if s[i] <= s[i-1]:
            return False
    return True

